/* Generated legacy bridge for CSS-module retirement. Keep new work in VUI/Tailwind components. */

/* source: app/AppShell legacy css */
:where(.vui-app-appshell).shell {
  display: grid;
  grid-template-rows: minmax(0, 1fr);
  height: 100dvh;
  min-height: 100dvh;
  overflow: hidden;
  isolation: isolate;
  --shell-topbar-height: 62px;
  --shell-page-end: var(--bg-canvas);
  --shell-surface: var(--surface-panel);
  --shell-surface-muted: color-mix(in srgb, var(--bg-canvas) 88%, transparent);
  --shell-surface-hover: var(--surface-panel-hover);
  --shell-panel: color-mix(in srgb, var(--bg-canvas) 98%, transparent);
  --shell-panel-soft: color-mix(in srgb, var(--fg-secondary) 98%, transparent);
  --shell-card: color-mix(in srgb, var(--bg-canvas) 82%, transparent);
  --shell-window-control-inset: 0px;
  --shell-shadow: color-mix(in srgb, var(--bg-canvas) 28%, transparent);
  --shell-star-color: color-mix(in srgb, var(--accent-warm) 74%, transparent);
  --shell-star-muted: color-mix(in srgb, var(--accent-warm) 34%, transparent);
  --shell-star-faint: color-mix(in srgb, var(--accent-warm) 20%, transparent);
  --shell-nebula-cool: color-mix(in srgb, var(--accent-warm) 18%, transparent);
  --shell-nebula-warm: color-mix(in srgb, var(--accent-warm) 11%, transparent);
  background:
    radial-gradient(ellipse at 52% -18%, color-mix(in srgb, var(--accent-warm) 14%, transparent) 0 18%, transparent 52%),
    radial-gradient(circle at 16% 18%, var(--shell-nebula-cool) 0 11%, transparent 34%),
    radial-gradient(circle at 82% 8%, var(--shell-nebula-warm) 0 9%, transparent 31%),
    var(--vui-gradient-route-soft),
    var(--vui-gradient-route-soft),
    var(--vui-gradient-route-soft);
  background-size: auto, auto, auto, 42px 42px, 42px 42px, auto;
  color: var(--fg-primary);
}

:where(.vui-app-appshell).shell[data-theme-background="custom"] {
  --theme-background-overlay-start: color-mix(in srgb, var(--bg-canvas) 56%, transparent);
  --theme-background-overlay-mid: color-mix(in srgb, var(--bg-canvas) 44%, transparent);
  --theme-background-overlay-end: color-mix(in srgb, var(--bg-canvas) 68%, transparent);
  --theme-background-star-opacity: 0.2;
  --theme-background-blur: 1px;
  --shell-surface-muted: color-mix(in srgb, var(--bg-canvas) 82%, transparent);
  --shell-panel: color-mix(in srgb, var(--bg-canvas) 94%, transparent);
  --shell-panel-soft: color-mix(in srgb, var(--fg-secondary) 92%, transparent);
  --shell-card: color-mix(in srgb, var(--bg-canvas) 78%, transparent);
  background:
    var(--vui-gradient-route-soft),
    var(--workbench-theme-background-image),
    var(--vui-gradient-route-soft);
  background-position: center, center, center;
  background-size: auto, cover, auto;
  background-repeat: no-repeat, no-repeat, no-repeat;
  background-attachment: fixed, fixed, fixed;
}

:where(.vui-app-appshell).shell[data-theme-background="custom"][data-theme-background-readability="soft"] {
  --theme-background-overlay-start: color-mix(in srgb, var(--bg-canvas) 38%, transparent);
  --theme-background-overlay-mid: color-mix(in srgb, var(--bg-canvas) 26%, transparent);
  --theme-background-overlay-end: color-mix(in srgb, var(--bg-canvas) 50%, transparent);
  --theme-background-star-opacity: 0.24;
  --theme-background-blur: 0px;
  --shell-surface-muted: color-mix(in srgb, var(--bg-canvas) 72%, transparent);
  --shell-panel: color-mix(in srgb, var(--bg-canvas) 88%, transparent);
  --shell-panel-soft: color-mix(in srgb, var(--fg-secondary) 86%, transparent);
  --shell-card: color-mix(in srgb, var(--bg-canvas) 66%, transparent);
}

:where(.vui-app-appshell).shell[data-theme-background="custom"][data-theme-background-readability="standard"] {
  --theme-background-overlay-start: color-mix(in srgb, var(--bg-canvas) 56%, transparent);
  --theme-background-overlay-mid: color-mix(in srgb, var(--bg-canvas) 44%, transparent);
  --theme-background-overlay-end: color-mix(in srgb, var(--bg-canvas) 68%, transparent);
  --theme-background-star-opacity: 0.2;
  --theme-background-blur: 1px;
}

:where(.vui-app-appshell).shell[data-theme-background="custom"][data-theme-background-readability="strong"] {
  --theme-background-overlay-start: color-mix(in srgb, var(--bg-canvas) 74%, transparent);
  --theme-background-overlay-mid: color-mix(in srgb, var(--bg-canvas) 62%, transparent);
  --theme-background-overlay-end: color-mix(in srgb, var(--bg-canvas) 82%, transparent);
  --theme-background-star-opacity: 0.14;
  --theme-background-blur: 2px;
  --shell-surface-muted: color-mix(in srgb, var(--bg-canvas) 90%, transparent);
  --shell-panel: color-mix(in srgb, var(--bg-canvas) 97%, transparent);
  --shell-panel-soft: color-mix(in srgb, var(--fg-secondary) 96%, transparent);
  --shell-card: color-mix(in srgb, var(--bg-canvas) 86%, transparent);
}

:where(.vui-app-appshell).shell::before,
:where(.vui-app-appshell).shell::after {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
}

:where(.vui-app-appshell).shell::before {
  opacity: 0.95;
  background-image:
    radial-gradient(circle at 8% 18%, var(--shell-star-color) 0 1px, transparent 1.6px),
    radial-gradient(circle at 22% 72%, var(--shell-star-muted) 0 1px, transparent 1.4px),
    radial-gradient(circle at 38% 28%, color-mix(in srgb, var(--fg-primary) 52%, transparent) 0 1px, transparent 1.5px),
    radial-gradient(circle at 67% 12%, color-mix(in srgb, var(--accent-warm) 55%, transparent) 0 1px, transparent 1.7px),
    radial-gradient(circle at 82% 64%, color-mix(in srgb, var(--fg-primary) 42%, transparent) 0 1px, transparent 1.5px),
    radial-gradient(circle at 92% 34%, var(--shell-star-muted) 0 1px, transparent 1.4px),
    radial-gradient(circle, var(--shell-star-faint) 0 0.8px, transparent 1.2px),
    radial-gradient(circle, color-mix(in srgb, var(--fg-primary) 16%, transparent) 0 0.7px, transparent 1px);
  background-size:
    263px 211px,
    307px 239px,
    359px 293px,
    421px 271px,
    331px 367px,
    503px 317px,
    89px 113px,
    137px 173px;
  background-position:
    0 0,
    28px 34px,
    76px 12px,
    120px 48px,
    38px 90px,
    144px 24px,
    0 0,
    44px 58px;
  filter: drop-shadow(0 0 5px color-mix(in srgb, var(--accent-warm) 28%, transparent));
}

:where(.vui-app-appshell).shell::after {
  opacity: 0.78;
  background:
    radial-gradient(ellipse at 50% 102%, color-mix(in srgb, var(--accent-warm) 16%, transparent), transparent 42%),
    radial-gradient(circle at 20% 88%, color-mix(in srgb, var(--accent-warm) 12%, transparent), transparent 28%),
    radial-gradient(circle at 78% 82%, color-mix(in srgb, var(--accent-warm) 10%, transparent), transparent 30%),
    var(--vui-gradient-route-soft),
    var(--vui-gradient-route-soft);
  mix-blend-mode: screen;
}

:where(.vui-app-appshell).shell[data-theme="light"] {
  --shell-page-end: var(--bg-canvas);
  --shell-surface: color-mix(in srgb, var(--surface-panel) 92%, transparent);
  --shell-surface-muted: color-mix(in srgb, var(--surface-panel) 84%, transparent);
  --shell-surface-hover: color-mix(in srgb, var(--surface-panel-hover) 94%, transparent);
  --shell-panel: color-mix(in srgb, var(--surface-panel) 94%, transparent);
  --shell-panel-soft: color-mix(in srgb, var(--surface-panel) 88%, transparent);
  --shell-card: color-mix(in srgb, var(--surface-card) 84%, transparent);
  --shell-shadow: color-mix(in srgb, var(--fg-tertiary) 12%, transparent);
  --shell-star-color: color-mix(in srgb, var(--accent-warm) 20%, transparent);
  --shell-star-muted: color-mix(in srgb, var(--fg-tertiary) 14%, transparent);
  --shell-star-faint: color-mix(in srgb, var(--accent-warm) 8%, transparent);
  --shell-nebula-cool: color-mix(in srgb, var(--accent-warm) 9%, transparent);
  --shell-nebula-warm: color-mix(in srgb, var(--fg-tertiary) 8%, transparent);
  background:
    radial-gradient(ellipse at 52% -18%, color-mix(in srgb, var(--accent-warm) 8%, transparent) 0 18%, transparent 52%),
    radial-gradient(circle at 16% 18%, var(--shell-nebula-cool) 0 11%, transparent 34%),
    radial-gradient(circle at 82% 8%, var(--shell-nebula-warm) 0 9%, transparent 31%),
    var(--vui-gradient-route-soft);
}

:where(.vui-app-appshell).shell[data-theme="light"][data-theme-background="custom"] {
  --theme-background-overlay-start: color-mix(in srgb, var(--bg-canvas) 50%, transparent);
  --theme-background-overlay-mid: color-mix(in srgb, var(--bg-canvas) 34%, transparent);
  --theme-background-overlay-end: color-mix(in srgb, var(--bg-canvas) 62%, transparent);
  --theme-background-star-opacity: 0.18;
  --theme-background-blur: 1px;
  --shell-surface-muted: color-mix(in srgb, var(--surface-panel) 78%, transparent);
  --shell-panel: color-mix(in srgb, var(--surface-panel) 88%, transparent);
  --shell-panel-soft: color-mix(in srgb, var(--surface-panel) 82%, transparent);
  --shell-card: color-mix(in srgb, var(--surface-card) 76%, transparent);
  background:
    var(--vui-gradient-route-soft),
    var(--workbench-theme-background-image),
    var(--vui-gradient-route-soft);
  background-position: center, center, center;
  background-size: auto, cover, auto;
  background-repeat: no-repeat, no-repeat, no-repeat;
  background-attachment: fixed, fixed, fixed;
}

:where(.vui-app-appshell).shell[data-theme="light"][data-theme-background="custom"][data-theme-background-readability="soft"] {
  --theme-background-overlay-start: color-mix(in srgb, var(--bg-canvas) 30%, transparent);
  --theme-background-overlay-mid: color-mix(in srgb, var(--bg-canvas) 18%, transparent);
  --theme-background-overlay-end: color-mix(in srgb, var(--bg-canvas) 46%, transparent);
  --theme-background-star-opacity: 0.22;
  --theme-background-blur: 0px;
  --shell-surface-muted: color-mix(in srgb, var(--surface-panel) 68%, transparent);
  --shell-panel: color-mix(in srgb, var(--surface-panel) 80%, transparent);
  --shell-panel-soft: color-mix(in srgb, var(--surface-panel) 72%, transparent);
  --shell-card: color-mix(in srgb, var(--surface-card) 64%, transparent);
}

:where(.vui-app-appshell).shell[data-theme="light"][data-theme-background="custom"][data-theme-background-readability="strong"] {
  --theme-background-overlay-start: color-mix(in srgb, var(--bg-canvas) 72%, transparent);
  --theme-background-overlay-mid: color-mix(in srgb, var(--bg-canvas) 60%, transparent);
  --theme-background-overlay-end: color-mix(in srgb, var(--bg-canvas) 80%, transparent);
  --theme-background-star-opacity: 0.12;
  --theme-background-blur: 2px;
  --shell-surface-muted: color-mix(in srgb, var(--surface-panel) 90%, transparent);
  --shell-panel: color-mix(in srgb, var(--surface-panel) 96%, transparent);
  --shell-panel-soft: color-mix(in srgb, var(--surface-panel) 92%, transparent);
  --shell-card: color-mix(in srgb, var(--surface-card) 88%, transparent);
}

:where(.vui-app-appshell).shell[data-theme="light"]::before {
  opacity: 0.34;
  filter: none;
}

:where(.vui-app-appshell).shell[data-theme-background="custom"]::before {
  opacity: var(--theme-background-star-opacity);
  -webkit-backdrop-filter: blur(var(--theme-background-blur));
  backdrop-filter: blur(var(--theme-background-blur));
}

:where(.vui-app-appshell).shell[data-theme="light"]::after {
  opacity: 0.28;
  mix-blend-mode: multiply;
}

:where(.vui-app-appshell).shutdownOverlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 24px;
  background: var(--surface-overlay);
  backdrop-filter: blur(12px);
}

:where(.vui-app-appshell).shutdownPanel {
  width: min(440px, 100%);
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 20px 22px;
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  background:
    var(--vui-gradient-route-soft),
    var(--shell-panel);
  box-shadow: var(--vui-shadow-soft);
}

:where(.vui-app-appshell).startupOverlay {
  position: fixed;
  inset: 0;
  z-index: 45;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    var(--vui-gradient-route-soft),
    var(--bg-canvas);
}

:where(.vui-app-appshell).startupPanel {
  width: min(460px, 100%);
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 22px;
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  background:
    var(--vui-gradient-route-soft),
    var(--shell-panel);
  box-shadow: var(--vui-shadow-soft);
}

:where(.vui-app-appshell).startupSpinner {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  flex: 0 0 auto;
  border: 1px solid var(--border-soft);
  border-radius: 8px;
  background: var(--shell-card);
  color: var(--accent-warm-2);
}

:where(.vui-app-appshell).startupCopy {
  display: grid;
  gap: 7px;
  min-width: 0;
}

:where(.vui-app-appshell).startupKicker {
  color: var(--accent-warm-2);
  font-size: var(--vui-font-sm);
}

:where(.vui-app-appshell).startupCopy strong {
  color: var(--fg-primary);
  font-size: 1rem;
}

:where(.vui-app-appshell).startupCopy p {
  margin: 0;
  color: var(--fg-secondary);
  line-height: 1.5;
}

:where(.vui-app-appshell).shutdownCopy {
  display: grid;
  gap: 6px;
  min-width: 0;
}

:where(.vui-app-appshell).shutdownCopy strong {
  font-size: 1rem;
}

:where(.vui-app-appshell).shutdownCopy p {
  margin: 0;
  color: var(--fg-secondary);
  line-height: 1.5;
  white-space: pre-line;
}

:where(.vui-app-appshell).shutdownCancelButton {
  justify-self: start;
  min-height: 32px;
  margin-top: 8px;
  padding: 0 12px;
  border: 1px solid var(--border-strong);
  border-radius: 6px;
  background: var(--shell-card);
  color: var(--fg-primary);
  font: inherit;
  font-size: var(--vui-font-chat);
  cursor: pointer;
}

:where(.vui-app-appshell).shutdownCancelButton:hover:not(:disabled),
:where(.vui-app-appshell).shutdownCancelButton:focus-visible:not(:disabled) {
  border-color: var(--accent-warm-2);
  color: var(--accent-warm-2);
}

:where(.vui-app-appshell).shutdownCancelButton:disabled {
  cursor: wait;
  opacity: 0.64;
}

:where(.vui-app-appshell).shutdownIconSpin,
:where(.vui-app-appshell).shutdownIconStill {
  flex: 0 0 auto;
  color: var(--accent-warm-2);
}

:where(.vui-app-appshell).shutdownIconSpin {
  animation: shell-spin 900ms linear infinite;
}

:where(.vui-app-appshell).topBar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  min-height: var(--shell-topbar-height);
  padding: 9px calc(16px + var(--shell-window-control-inset)) 9px 16px;
  pointer-events: none;
  -webkit-app-region: drag;
}

:where(.vui-app-appshell).topBar > * {
  -webkit-app-region: no-drag;
}

:where(.vui-app-appshell).topBar::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--shell-surface-muted);
  border-bottom: 1px solid var(--border-hairline);
  backdrop-filter: blur(16px);
  pointer-events: none;
}

:where(.vui-app-appshell).shell[data-theme="light"] .topBar::before {
  background:
    var(--vui-gradient-route-soft),
    color-mix(in srgb, var(--surface-panel) 68%, transparent);
  box-shadow: var(--vui-shadow-hairline);
}

:where(.vui-app-appshell).shell[data-desktop-shell="electron"] .topBar {
  --shell-window-control-inset: 136px;
}

:where(.vui-app-appshell).shell[data-topbar-mode="hidden"] {
  --shell-topbar-height: 0px;
}

:where(.vui-app-appshell).shell[data-topbar-mode="hidden"] .topBar {
  display: none;
}

:where(.vui-app-appshell).topBarRestoreButton {
  position: fixed;
  top: 10px;
  right: 10px;
  z-index: 22;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 32px;
  max-width: min(176px, calc(100vw - 20px));
  padding: 6px 10px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-control);
  color: var(--fg-secondary);
  background: color-mix(in srgb, var(--shell-surface) 90%, transparent);
  box-shadow: var(--vui-shadow-soft);
  -webkit-backdrop-filter: blur(14px);
  backdrop-filter: blur(14px);
  cursor: pointer;
  font: inherit;
  font-size: var(--vui-font-md);
  -webkit-app-region: no-drag;
  app-region: no-drag;
  transition: border-color 150ms ease, background-color 150ms ease, color 150ms ease;
}

:where(.vui-app-appshell).topBarRestoreButton:hover,
:where(.vui-app-appshell).topBarRestoreButton:focus-visible {
  border-color: var(--border-strong);
  color: var(--fg-primary);
  background: var(--shell-panel-soft);
}

:where(.vui-app-appshell).topBarRestoreButton:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent-cool) 46%, transparent);
  outline-offset: 2px;
}

:where(.vui-app-appshell).topBarRestoreButton span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

:where(.vui-app-appshell).topBarRestoreButton[data-vui] [data-slot="vui-button-label"] {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

:where(.vui-app-appshell).brandBlock {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  pointer-events: auto;
}

:where(.vui-app-appshell).returnButton {
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-control);
  background: color-mix(in srgb, var(--shell-surface) 88%, transparent);
  color: var(--fg-secondary);
  cursor: pointer;
  -webkit-app-region: no-drag;
  app-region: no-drag;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

:where(.vui-app-appshell).returnButton:hover {
  border-color: color-mix(in srgb, var(--accent-cool) 34%, var(--border-soft));
  background: color-mix(in srgb, var(--accent-cool) 10%, var(--shell-surface));
  color: var(--fg-primary);
}

:where(.vui-app-appshell).returnButton:focus-visible {
  outline: 2px solid color-mix(in srgb, var(--accent-cool) 46%, transparent);
  outline-offset: 2px;
}

:where(.vui-app-appshell).brandCopy {
  display: grid;
  grid-template-columns: max-content max-content;
  grid-template-areas:
    "brand version"
    "subtle subtle";
  align-items: center;
  gap: 2px 7px;
  min-width: 0;
  line-height: 1;
}

:where(.vui-app-appshell).brand {
  grid-area: brand;
  font-family: var(--font-display);
  font-size: 1.1rem;
  line-height: 1;
  letter-spacing: 0;
  white-space: nowrap;
}

:where(.vui-app-appshell).versionPill {
  grid-area: version;
  flex: 0 0 auto;
  padding: 2px 6px;
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  background: color-mix(in srgb, var(--shell-surface-muted) 78%, transparent);
  color: var(--fg-tertiary);
  font-size: var(--vui-font-xs);
  font-weight: 600;
  line-height: 1.2;
  white-space: nowrap;
}

:where(.vui-app-appshell).brandSubtle {
  grid-area: subtle;
  max-width: min(230px, 34vw);
  min-width: 0;
  overflow: hidden;
  color: var(--fg-tertiary);
  font-size: var(--vui-font-xs);
  line-height: 1.08;
  text-overflow: ellipsis;
  white-space: nowrap;
}

:where(.vui-app-appshell).topClock {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  min-height: 32px;
  max-width: min(38vw, 300px);
  padding: 7px 10px;
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  background: var(--shell-surface);
  color: var(--fg-secondary);
  font-size: var(--vui-font-sm);
  line-height: 1;
  white-space: nowrap;
}

:where(.vui-app-appshell).topClock span:last-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

:where(.vui-app-appshell).activeWorkChip {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  max-width: min(28vw, 300px);
  min-height: 32px;
  padding: 6px 9px;
  border: 1px solid color-mix(in srgb, var(--accent-warm) 36%, var(--border-soft));
  border-radius: 999px;
  background:
    var(--vui-gradient-route-soft),
    var(--shell-surface);
  color: var(--fg-secondary);
  font-size: var(--vui-font-sm);
  line-height: 1;
  white-space: nowrap;
  box-shadow: var(--vui-shadow-soft);
  outline: none;
}

:where(.vui-app-appshell).activeWorkKicker {
  flex: 0 0 auto;
  color: var(--fg-tertiary);
  font-size: var(--vui-font-xs);
}

:where(.vui-app-appshell).activeWorkChip strong {
  flex: 0 0 auto;
  color: var(--fg-primary);
  font-size: var(--vui-font-md);
}

:where(.vui-app-appshell).activeWorkStatus,
:where(.vui-app-appshell).activeWorkMore {
  flex: 0 0 auto;
  padding: 3px 7px;
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  background: color-mix(in srgb, var(--shell-card) 74%, transparent);
  color: var(--fg-primary);
